selector_to_html = {"a[href=\"#rpu-driver-and-runtime-vendor-provided\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.2 RPU driver and runtime (vendor-provided)<a class=\"headerlink\" href=\"#rpu-driver-and-runtime-vendor-provided\" title=\"Link to this heading\">#</a></h3><p>Install, per the vendor\u2019s instructions:</p>", "a[href=\"#rpu-llvm-toolchain-vendor-provided\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.3 RPU LLVM toolchain (vendor-provided)<a class=\"headerlink\" href=\"#rpu-llvm-toolchain-vendor-provided\" title=\"Link to this heading\">#</a></h3><p>The RPU backend uses a custom LLVM as its <code class=\"docutils literal notranslate\"><span class=\"pre\">.rpubin</span></code> emitter. Point\n<code class=\"docutils literal notranslate\"><span class=\"pre\">RPU_LLVM_ROOT</span></code> at the toolchain install prefix (the directory containing\n<code class=\"docutils literal notranslate\"><span class=\"pre\">bin/clang</span></code>):</p>", "a[href=\"#testing-and-validation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Testing and validation<a class=\"headerlink\" href=\"#testing-and-validation\" title=\"Link to this heading\">#</a></h2><h3>3.1 Unit tests<a class=\"headerlink\" href=\"#unit-tests\" title=\"Link to this heading\">#</a></h3><p>The compile tests drive the real toolchain, so set <code class=\"docutils literal notranslate\"><span class=\"pre\">RPU_LLVM_ROOT</span></code> first (the\ndirectory containing <code class=\"docutils literal notranslate\"><span class=\"pre\">bin/clang</span></code>). If it is unset or its path is missing, the\ntests stop with a clear message naming the variable.</p>", "a[href=\"#installation-commands\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Installation Commands<a class=\"headerlink\" href=\"#installation-commands\" title=\"Link to this heading\">#</a></h2><p>The RPU backend is built from source on the board. There is no source-free\n(pip wheel) installation.</p>", "a[href=\"#build-and-run-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Hardware and OS<a class=\"headerlink\" href=\"#hardware-and-os\" title=\"Link to this heading\">#</a></h3><p>There is no Docker image for the RPU backend; all steps below run natively on\nthe R1 SoC board. Verify the device node:</p>", "a[href=\"#unit-tests\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.1 Unit tests<a class=\"headerlink\" href=\"#unit-tests\" title=\"Link to this heading\">#</a></h3><p>The compile tests drive the real toolchain, so set <code class=\"docutils literal notranslate\"><span class=\"pre\">RPU_LLVM_ROOT</span></code> first (the\ndirectory containing <code class=\"docutils literal notranslate\"><span class=\"pre\">bin/clang</span></code>). If it is unset or its path is missing, the\ntests stop with a clear message naming the variable.</p>", "a[href=\"#hardware-and-os\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.1 Hardware and OS<a class=\"headerlink\" href=\"#hardware-and-os\" title=\"Link to this heading\">#</a></h3><p>There is no Docker image for the RPU backend; all steps below run natively on\nthe R1 SoC board. Verify the device node:</p>", "a[href=\"#huixi-intelligence-rpu3-6\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Huixi Intelligence\uff08\u8f89\u7fb2\u667a\u80fd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/rpu/\">rpu</a>3.6<a class=\"headerlink\" href=\"#huixi-intelligence-rpu3-6\" title=\"Link to this heading\">#</a></h1><p>The <strong>Rhino RPU</strong> is the AI accelerator inside Huixi Intelligence\u2019s \u5149\u81f3 R1 SoC\n(<a class=\"reference external\" href=\"https://www.rhino.auto/\">rhino.auto</a>). Unlike the CPU/GPU backends, the RPU\nbackend has <strong>no preinstalled image and no CPU simulator</strong> \u2014 it compiles and\nruns only on a physical R1 SoC board, and its driver, runtime, and toolchain are\nobtained from the vendor. Build and test directly on the board.</p>", "a[href=\"#build-from-source\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 Build from source<a class=\"headerlink\" href=\"#build-from-source\" title=\"Link to this heading\">#</a></h3><p>The Triton MLIR LLVM is downloaded automatically from the public oaitriton blob\nthe first time setup runs; no manual action is needed.</p>", "a[href=\"#on-board-launch-kernel-check\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2 On-board launch_kernel check<a class=\"headerlink\" href=\"#on-board-launch-kernel-check\" title=\"Link to this heading\">#</a></h3><p>This needs the <code class=\"docutils literal notranslate\"><span class=\"pre\">launch_kernel_runner</span></code> CLI, a thin front-end over the\n<code class=\"docutils literal notranslate\"><span class=\"pre\">rhino-launch-kernel</span></code> runtime library. Build it together with the backend by\nenabling <code class=\"docutils literal notranslate\"><span class=\"pre\">RPU_BUILD_LAUNCH_RUNNER</span></code> (off by default; it needs the\n<code class=\"docutils literal notranslate\"><span class=\"pre\">rhino-launch-kernel</span></code> install), then run the smoke test on a board with\n<code class=\"docutils literal notranslate\"><span class=\"pre\">/dev/rpu</span></code>:</p>", "a[href=\"#pull-the-source-code\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 Pull the source code<a class=\"headerlink\" href=\"#pull-the-source-code\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
